/**
 * Epson EEPROM model database.
 *
 * Two bytes of read key (the model code), an 8-char write key, the EEPROM
 * addresses of the waste-ink counters, the factory reset write map, and the
 * statistics counters (big-endian: first address is the most significant
 * byte) for each supported model. Extracted from the PRINTER_CONFIG table
 * of the open-source epson_print_conf project (Ircama/epson_print_conf,
 * EUPL-1.2, https://github.com/Ircama/epson_print_conf), with its alias
 * and same-as entries expanded using that project's merge semantics
 * ({**target, **self}).
 */
export interface EpsonModelEntry {
  /** 2-byte EEPROM read key (model code); sent little-endian on the wire. */
  readKey: [number, number];
  /** 8-char EEPROM write key, plain ASCII; +1 Caesar shift is applied on the wire. */
  writeKey: string;
  mainWaste: { oids: number[]; divider: number };
  borderlessWaste?: { oids: number[]; divider: number };
  /** Factory reset map: EEPROM address -> byte value to write. */
  rawReset: Record<string, number>;
  /** Statistics counters: name -> addresses (first address = most significant byte). */
  stats?: Record<string, number[]>;
  /** EEPROM addresses holding the ASCII serial number (fallback when ST2 omits it). */
  serial?: number[];
}

